import{_ as t,o as n,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse(`{"title":"Logement et Protection de l'Environnement","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0039-住房与环境保障.md","filePath":"fr/0039-住房与环境保障.md"}`),a={name:"fr/0039-住房与环境保障.md"};function o(r,e,l,u,d,c){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="logement-et-protection-de-l-environnement" tabindex="-1">Logement et Protection de l&#39;Environnement <a class="header-anchor" href="#logement-et-protection-de-l-environnement" aria-label="Permalink to &quot;Logement et Protection de l&#39;Environnement&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>39</td></tr><tr><td>Module</td><td>Types de Civilisation et Systèmes Sociaux</td></tr><tr><td>Mots-clés</td><td>Garantie du logement, Protection de l&#39;environnement, Symbiose écologique, Espaces vivables, Développement durable</td></tr></tbody></table><h2 id="i-concepts-fondamentaux-du-logement-et-de-la-protection-de-l-environnement" tabindex="-1">I. Concepts fondamentaux du logement et de la protection de l&#39;environnement <a class="header-anchor" href="#i-concepts-fondamentaux-du-logement-et-de-la-protection-de-l-environnement" aria-label="Permalink to &quot;I. Concepts fondamentaux du logement et de la protection de l&#39;environnement&quot;">​</a></h2><p>« À chacun son toit » est une question vitale fondamentale que toute civilisation doit affronter. À l&#39;époque du Système de Culture Prédatrice, le logement et la terre étaient monopolisés par une poignée de puissants et de sectes, et les masses du bas étaient souvent sans domicile fixe, contraintes de cultiver et de vivre dans des environnements hostiles. Plus grave encore, la culture prédatrice causait d&#39;énormes dégâts à l&#39;environnement — les veines d&#39;esprit étaient surexploitées, l&#39;écologie gravement polluée, les ressources planétaires consommées de façon prédatrice, transformant de nombreuses planètes autrefois habitables en terres désolées.</p><p>Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, la garantie du logement et la protection de l&#39;environnement sont devenues des contenus fondamentaux de la construction des institutions sociales. Le concept fondamental du logement et de la protection de l&#39;environnement peut se résumer en seize caractères : « Un Toit pour Chacun, Symbiose Écologique, Développement Durable, Vivable pour les Dix Mille Races ».</p><p>Les objectifs fondamentaux du logement et de la protection de l&#39;environnement comprennent :</p><ol><li><strong>Garantir le droit fondamental au logement</strong> : veiller à ce que chaque vie symbiotique obtienne un logement décent, sûr et adapté, et que les problèmes de logement n&#39;affectent pas la survie et l&#39;évolution</li><li><strong>Protéger l&#39;environnement écologique</strong> : établir un système complet de protection de l&#39;environnement, maintenir l&#39;équilibre écologique et empêcher les activités de culture de nuire à l&#39;environnement</li><li><strong>Construire des espaces vivables</strong> : par la planification scientifique et les moyens technologiques, construire des espaces vivables adaptés à la culture et à la vie</li><li><strong>Réaliser le développement durable</strong> : tout en répondant aux besoins de la génération actuelle, ne pas nuire à la capacité des générations futures à répondre à leurs besoins, réalisant l&#39;utilisation durable des ressources et de l&#39;environnement</li><li><strong>Promouvoir l&#39;habitabilité des Dix Mille Races</strong> : la construction du logement et de l&#39;environnement tient pleinement compte des caractéristiques physiologiques et des habitudes de vie des différentes races, garantissant que les Dix Mille Races puissent toutes vivre confortablement</li></ol><h2 id="ii-le-systeme-de-garantie-du-logement" tabindex="-1">II. Le système de garantie du logement <a class="header-anchor" href="#ii-le-systeme-de-garantie-du-logement" aria-label="Permalink to &quot;II. Le système de garantie du logement&quot;">​</a></h2><p>Le système de garantie du logement de la civilisation symbiotique suit les principes de « garantir l&#39;essentiel, promouvoir l&#39;amélioration, multiples canaux, durabilité », construisant un système d&#39;approvisionnement en logement à plusieurs niveaux :</p><h3 id="_2-1-les-trois-niveaux-de-l-approvisionnement-en-logement" tabindex="-1">2.1 Les trois niveaux de l&#39;approvisionnement en logement <a class="header-anchor" href="#_2-1-les-trois-niveaux-de-l-approvisionnement-en-logement" aria-label="Permalink to &quot;2.1 Les trois niveaux de l&#39;approvisionnement en logement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Nom</th><th>Public visé</th><th>Type de logement</th><th>Loyer/prix</th></tr></thead><tbody><tr><td>Premier niveau</td><td>Logement Garanti</td><td>Groupes à faible revenu, cultivateurs novices</td><td>Appartements de culture de base, dortoirs collectifs</td><td>Gratuit ou loyer extrêmement bas</td></tr><tr><td>Deuxième niveau</td><td>Logement Amélioré</td><td>Groupes à revenu moyen, cultivateurs intermédiaires</td><td>Résidences de culture standard, appartements familiaux</td><td>Prix coûtant ou loyer bas</td></tr><tr><td>Troisième niveau</td><td>Logement Commercial</td><td>Groupes à revenu élevé, cultivateurs avancés</td><td>Résidences de culture haut de gamme, demeures cavernes indépendantes</td><td>Prix du marché</td></tr></tbody></table><h3 id="_2-2-le-systeme-de-logement-garanti" tabindex="-1">2.2 Le système de logement garanti <a class="header-anchor" href="#_2-2-le-systeme-de-logement-garanti" aria-label="Permalink to &quot;2.2 Le système de logement garanti&quot;">​</a></h3><p>Le logement garanti est le cœur du système de garantie du logement, assurant le droit fondamental au logement de chaque vie symbiotique :</p><ul><li><strong>Appartements de culture de base</strong> : petits appartements pour les cultivateurs novices et les individus seuls, équipés d&#39;installations de culture de base, à loyer extrêmement bas ou gratuit</li><li><strong>Dortoirs collectifs</strong> : hébergement collectif pour les disciples de sectes, les étudiants et les travailleurs collectifs, avec espaces de culture partagés</li><li><strong>Logements garantis familiaux</strong> : logements complets pour les familles à faible revenu, de taille modérée et d&#39;équipements complets</li><li><strong>Logements garantis spéciaux</strong> : logements adaptés pour les vies handicapées, les races spéciales, les cultivateurs âgés et d&#39;autres groupes spéciaux</li></ul><p>La demande et l&#39;attribution du logement garanti suivent les principes de « transparence, équité et justice », les demandes et examens étant effectués via le réseau symbiotique, et les résultats d&#39;attribution rendus publics et transparents.</p><h3 id="_2-3-le-systeme-de-logement-ameliore" tabindex="-1">2.3 Le système de logement amélioré <a class="header-anchor" href="#_2-3-le-systeme-de-logement-ameliore" aria-label="Permalink to &quot;2.3 Le système de logement amélioré&quot;">​</a></h3><p>Le logement amélioré vise les groupes à revenu moyen ayant une certaine capacité économique, fourni au prix coûtant ou à loyer réduit :</p><ul><li><strong>Résidences de culture standard</strong> : logements complets avec pièce de culture indépendante, adaptés aux individus et familles ayant une certaine base de culture</li><li><strong>Appartements familiaux</strong> : appartements de taille moyenne adaptés aux familles, avec espaces d&#39;activités pour enfants et zones de culture familiale</li><li><strong>Appartements pour talents</strong> : logements préférentiels pour les talents de haut niveau introduits et le personnel technique professionnel</li></ul><p>L&#39;offre de logement amélioré est ajustée dynamiquement selon la demande, garantissant que les groupes à revenu moyen puissent obtenir un logement adapté à des coûts raisonnables.</p><h3 id="_2-4-le-systeme-de-logement-commercial" tabindex="-1">2.4 Le système de logement commercial <a class="header-anchor" href="#_2-4-le-systeme-de-logement-commercial" aria-label="Permalink to &quot;2.4 Le système de logement commercial&quot;">​</a></h3><p>Le logement commercial vise les groupes à revenu élevé et est fourni au prix du marché :</p><ul><li><strong>Résidences de culture haut de gamme</strong> : résidences de luxe équipées d&#39;installations de culture avancées</li><li><strong>Demeures cavernes indépendantes</strong> : demeures cavernes de culture disposant d&#39;un espace indépendant et d&#39;une alimentation énergétique</li><li><strong>Résidences sur mesure</strong> : résidences spéciales personnalisées selon les besoins individuels</li></ul><p>Les transactions de logement commercial suivent les règles du marché, mais le gouvernement régule par la taxe foncière, la gestion des terres et d&#39;autres moyens, empêchant une hausse excessive des prix et la spéculation immobilière.</p><h3 id="_2-5-equipement-des-espaces-de-culture" tabindex="-1">2.5 Équipement des espaces de culture <a class="header-anchor" href="#_2-5-equipement-des-espaces-de-culture" aria-label="Permalink to &quot;2.5 Équipement des espaces de culture&quot;">​</a></h3><p>Dans la civilisation symbiotique, le logement n&#39;est pas seulement un espace de vie, mais aussi un espace de culture. Chaque logement est équipé d&#39;installations de culture correspondant aux besoins de culture des résidents :</p><ul><li><strong>Zone de culture de base</strong> : chaque logement dispose d&#39;une zone de culture de base, équipée d&#39;interfaces d&#39;accès à l&#39;énergie de base</li><li><strong>Alimentation énergétique</strong> : alimentation énergétique stable des logements via le réseau symbiotique, répondant aux besoins de culture</li><li><strong>Isolation phonique et énergétique</strong> : les zones de culture disposent d&#39;installations d&#39;isolation phonique et de protection énergétique, empêchant la culture de déranger autrui</li><li><strong>Espaces de culture publics</strong> : les communautés disposent d&#39;espaces partagés tels que des salles de culture publiques et des salles d&#39;équipement de culture</li></ul><h2 id="iii-le-systeme-de-protection-de-l-environnement" tabindex="-1">III. Le système de protection de l&#39;environnement <a class="header-anchor" href="#iii-le-systeme-de-protection-de-l-environnement" aria-label="Permalink to &quot;III. Le système de protection de l&#39;environnement&quot;">​</a></h2><p>Le système de protection de l&#39;environnement de la civilisation symbiotique suit les principes de « prévention prioritaire, traitement global, restauration écologique, utilisation durable », construisant un cadre complet de protection de l&#39;environnement :</p><h3 id="_3-1-normes-environnementales-et-supervision" tabindex="-1">3.1 Normes environnementales et supervision <a class="header-anchor" href="#_3-1-normes-environnementales-et-supervision" aria-label="Permalink to &quot;3.1 Normes environnementales et supervision&quot;">​</a></h3><p>La civilisation symbiotique a formulé des normes environnementales strictes, encadrant l&#39;impact environnemental des activités de culture et de production :</p><ul><li><strong>Normes d&#39;émission énergétique</strong> : limitation stricte des émissions énergétiques générées pendant la culture et la production</li><li><strong>Normes d&#39;extraction des ressources</strong> : encadrement de l&#39;extraction des veines d&#39;esprit, des minéraux, des ressources biologiques, etc., empêchant la surexploitation</li><li><strong>Lignes rouges de protection écologique</strong> : délimiter des lignes rouges de protection écologique, à l&#39;intérieur desquelles toute activité destructrice est interdite</li><li><strong>Évaluation de l&#39;impact sur l&#39;environnement</strong> : les grands projets de culture et de construction doivent passer une évaluation de l&#39;impact sur l&#39;environnement</li></ul><p>La supervision de la protection de l&#39;environnement est assurée par des institutions de supervision environnementale dédiées, qui surveillent la qualité de l&#39;environnement en temps réel via le réseau symbiotique et imposent de lourdes sanctions aux activités illégales.</p><h3 id="_3-2-technologies-de-traitement-de-la-pollution" tabindex="-1">3.2 Technologies de traitement de la pollution <a class="header-anchor" href="#_3-2-technologies-de-traitement-de-la-pollution" aria-label="Permalink to &quot;3.2 Technologies de traitement de la pollution&quot;">​</a></h3><p>La civilisation symbiotique a développé des technologies avancées de traitement de la pollution :</p><ul><li><strong>Traitement de la pollution énergétique</strong> : par la filtration énergétique, la conversion énergétique et d&#39;autres technologies, traiter la pollution énergétique générée par les activités de culture</li><li><strong>Traitement de la pollution matérielle</strong> : par la bioremédiation, le traitement chimique, la purification physique et d&#39;autres technologies, traiter la pollution matérielle</li><li><strong>Traitement de la pollution par les lois</strong> : par le détachement des lois, la neutralisation des lois et d&#39;autres technologies, traiter la pollution environnementale causée par l&#39;érosion des lois</li><li><strong>Technologies de restauration écologique</strong> : par le Système de Circulation de la Vie et les technologies d&#39;ingénierie écologique, restaurer les écosystèmes endommagés</li></ul><h3 id="_3-3-utilisation-durable-des-ressources" tabindex="-1">3.3 Utilisation durable des ressources <a class="header-anchor" href="#_3-3-utilisation-durable-des-ressources" aria-label="Permalink to &quot;3.3 Utilisation durable des ressources&quot;">​</a></h3><p>La civilisation symbiotique met l&#39;accent sur l&#39;utilisation durable des ressources et s&#39;oppose au développement prédatoire :</p><ul><li><strong>Quotas d&#39;extraction des ressources</strong> : mise en œuvre de systèmes de quotas d&#39;extraction pour les ressources non renouvelables, garantissant l&#39;utilisation à long terme des ressources</li><li><strong>Recyclage des ressources</strong> : développer vigoureusement les technologies de recyclage des ressources, améliorant l&#39;efficacité d&#39;utilisation des ressources</li><li><strong>Développement des énergies renouvelables</strong> : développer activement les énergies renouvelables telles que l&#39;énergie solaire, éolienne, hydraulique et l&#39;énergie de champ</li><li><strong>Recherche de ressources alternatives</strong> : rechercher des substituts aux ressources rares, réduisant la dépendance aux ressources rares</li></ul><h3 id="_3-4-protection-et-restauration-ecologiques" tabindex="-1">3.4 Protection et restauration écologiques <a class="header-anchor" href="#_3-4-protection-et-restauration-ecologiques" aria-label="Permalink to &quot;3.4 Protection et restauration écologiques&quot;">​</a></h3><p>La civilisation symbiotique accorde une grande importance à la protection et à la restauration écologiques :</p><ul><li><strong>Réserves naturelles</strong> : établir des réserves naturelles à tous les niveaux, protégeant les espèces rares et les écosystèmes primitifs</li><li><strong>Projets de restauration écologique</strong> : restaurer les écosystèmes déjà endommagés, rétablissant l&#39;équilibre écologique</li><li><strong>Programmes de protection des espèces</strong> : protéger et élever les espèces en voie de disparition, empêchant leur extinction</li><li><strong>Mécanisme de compensation écologique</strong> : compenser les régions et groupes subissant des pertes dues à la protection écologique</li></ul><h2 id="iv-construction-d-espaces-vivables" tabindex="-1">IV. Construction d&#39;espaces vivables <a class="header-anchor" href="#iv-construction-d-espaces-vivables" aria-label="Permalink to &quot;IV. Construction d&#39;espaces vivables&quot;">​</a></h2><p>Sur la base du logement et de la protection de l&#39;environnement, la civilisation symbiotique promeut vigoureusement la construction d&#39;espaces vivables :</p><h3 id="_4-1-planification-urbaine" tabindex="-1">4.1 Planification urbaine <a class="header-anchor" href="#_4-1-planification-urbaine" aria-label="Permalink to &quot;4.1 Planification urbaine&quot;">​</a></h3><p>La planification urbaine de la civilisation symbiotique suit les principes de « compact, vert, intelligent et humain » :</p><ul><li><strong>Disposition compacte</strong> : les villes adoptent des dispositions compactes, réduisant l&#39;occupation des terres et la consommation d&#39;énergie des transports</li><li><strong>Espaces verts</strong> : les villes conservent d&#39;amples espaces verts tels que les zones végétalisées, les parcs et les zones humides</li><li><strong>Gestion intelligente</strong> : par le réseau symbiotique et les technologies intelligentes, réaliser la gestion intelligente des villes</li><li><strong>Attention humaine</strong> : la planification urbaine tient pleinement compte des besoins des groupes de différentes races, âges et capacités</li></ul><h3 id="_4-2-construction-de-communautes-de-culture" tabindex="-1">4.2 Construction de communautés de culture <a class="header-anchor" href="#_4-2-construction-de-communautes-de-culture" aria-label="Permalink to &quot;4.2 Construction de communautés de culture&quot;">​</a></h3><p>La civilisation symbiotique construit vigoureusement des communautés de culture intégrant résidence, culture et services :</p><ul><li><strong>Centres de culture communautaires</strong> : chaque communauté dispose d&#39;un centre de culture, fournissant des espaces de culture publics et un encadrement de culture</li><li><strong>Centres de services communautaires</strong> : fournir des services complets tels que santé, éducation, commerce et divertissement</li><li><strong>Espaces verts communautaires</strong> : les communautés conservent d&#39;amples espaces verts et de loisirs</li><li><strong>Culture communautaire</strong> : cultiver la culture communautaire, renforçant le sentiment d&#39;appartenance et la cohésion des résidents</li></ul><h3 id="_4-3-espaces-vivables-inter-plan" tabindex="-1">4.3 Espaces vivables inter-plan <a class="header-anchor" href="#_4-3-espaces-vivables-inter-plan" aria-label="Permalink to &quot;4.3 Espaces vivables inter-plan&quot;">​</a></h3><p>Avec l&#39;avancement de l&#39;exploration inter-plan, la civilisation symbiotique a commencé à construire des espaces vivables sur d&#39;autres plans :</p><ul><li><strong>Transformation de l&#39;habitabilité des plans</strong> : transformer les plans appropriés pour les rendre vivables, construisant de nouveaux espaces de résidence et de culture</li><li><strong>Migration écologique</strong> : migrer de manière planifiée la population des plans à ressources tendues vers des plans vivables nouvellement développés</li><li><strong>Logement inter-plan</strong> : fournir une garantie de logement inter-plan aux cultivateurs voyageant fréquemment entre les plans</li></ul><h2 id="v-differences-des-modeles-de-logement-et-d-environnement-entre-les-cinq-types-de-civilisation" tabindex="-1">V. Différences des modèles de logement et d&#39;environnement entre les cinq types de civilisation <a class="header-anchor" href="#v-differences-des-modeles-de-logement-et-d-environnement-entre-les-cinq-types-de-civilisation" aria-label="Permalink to &quot;V. Différences des modèles de logement et d&#39;environnement entre les cinq types de civilisation&quot;">​</a></h2><p>Les cinq types de civilisation symbiotique ont leurs propres caractéristiques en matière de modèles de logement et d&#39;environnement :</p><table tabindex="0"><thead><tr><th>Type</th><th>Caractéristiques du modèle de logement</th><th>Caractéristiques du modèle environnemental</th></tr></thead><tbody><tr><td>Type Intensif d&#39;Asie de l&#39;Est</td><td>Haute densité, intensif, dortoirs collectifs en majorité</td><td>Supervision stricte, gouvernance efficace, restauration rapide</td></tr><tr><td>Type Nordique de Bien-être</td><td>Haute garantie, haute qualité, personnalisé</td><td>Hautes normes, haut investissement, écologie prioritaire</td></tr><tr><td>Type Pluraliste Nord-Américain</td><td>Marchandisation, diversité, faible densité</td><td>Gouvernance de marché, portée par la technologie, protection des ressources</td></tr><tr><td>Type Social Européen Continental</td><td>Logement social, logement coopératif, répartition équilibrée</td><td>Participation associative, gouvernance délibérative, développement durable</td></tr><tr><td>Type de Rattrapage en Développement</td><td>Garantie prioritaire, construction rapide, amélioration progressive</td><td>Développement et protection à la fois, traitement ciblé</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le logement et la protection de l&#39;environnement sont la « pierre angulaire du bien-être » et la « barrière écologique » de la Civilisation Symbiotique de l&#39;Ancre. À travers le système de garantie du logement à plusieurs niveaux, le système complet de protection de l&#39;environnement et la construction scientifique d&#39;espaces vivables, la civilisation symbiotique a réalisé les objectifs de « Un Toit pour Chacun, Symbiose Écologique, Développement Durable, Vivable pour les Dix Mille Races ». La garantie du logement permet à chaque vie symbiotique de cultiver l&#39;esprit tranquille, et la protection de l&#39;environnement pose la base écologique du développement à long terme de la civilisation. Les deux se complètent, soutenant ensemble la progression commune des Dix Mille Races et le développement durable de la civilisation symbiotique.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>45-住房保障法 (Loi sur la garantie du logement)</li><li>46-环境保护法 (Loi sur la protection de l&#39;environnement)</li><li>32-北欧福利型文明 (Civilisation nordique de bien-être)</li></ul>',59)])])}const g=t(a,[["render",o]]);export{p as __pageData,g as default};
